#include <bits/stdc++.h>
using namespace std;
int main(){
    int T; cin>>T;
    while(T--){
        int n; cin>>n;
        vector<string> s(n);
        for(auto&x:s) cin>>x;
        vector<char> seen2(676,0), seen3(17576,0);
        auto id2=[&](char a,char b){return (a-'a')*26+(b-'a');};
        auto id3=[&](char a,char b,char c){return ((a-'a')*26+(b-'a'))*26+(c-'a');};
        bool yes=false;
        for(auto&w:s){
            int L=w.size();
            string r(w.rbegin(),w.rend());
            if(r==w) yes=true;
            if(!yes){
                if(L==2){
                    if(seen2[id2(r[0],r[1])]) yes=true;
                    for(char c='a';c<='z'&&!yes;c++) if(seen3[id3(r[0],r[1],c)]) yes=true;
                } else if(L==3){
                    if(seen3[id3(r[0],r[1],r[2])]) yes=true;
                    if(seen2[id2(r[0],r[1])]) yes=true;
                }
            }
            if(L==2) seen2[id2(w[0],w[1])]=1;
            else if(L==3) seen3[id3(w[0],w[1],w[2])]=1;
        }
        cout<<(yes?"YES":"NO")<<"\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,p; cin>>n>>p; string s; cin>>s; p--;
    long long total=0; int L=INT_MAX,R=-1;
    for(int k=0;k<n/2;k++){
        int d=abs((s[k]-'a')-(s[n-1-k]-'a'));
        d=min(d,26-d);
        if(d>0){ total+=d; L=min(L,k); R=max(R,k); }
    }
    if(R<0){ cout<<0<<"\n"; return 0; }
    int pp=min(p,n-1-p);
    int lo=min(L,pp), hi=max(R,pp);
    long long move=(hi-lo)+min(pp-lo,hi-pp);
    cout<<total+move<<"\n";
}

