using namespace std;
typedef long long ll;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int nr,ng,nb; scanf("%d %d %d",&nr,&ng,&nb);
        vector<ll> v[3];
        v[0].resize(nr); v[1].resize(ng); v[2].resize(nb);
        for(int c=0;c<3;c++){ for(auto&x:v[c]) scanf("%lld",&x); sort(v[c].begin(),v[c].end()); }
        int perm[6][3]={{0,1,2},{0,2,1},{1,0,2},{1,2,0},{2,0,1},{2,1,0}};
        ll best=LLONG_MAX;
        for(auto&p:perm){
            auto &A=v[p[0]], &B=v[p[1]], &C=v[p[2]];
            for(ll y:B){
                auto it=upper_bound(A.begin(),A.end(),y);
                if(it==A.begin()) continue;
                ll x=*(it-1);
                auto jt=lower_bound(C.begin(),C.end(),y);
                if(jt==C.end()) continue;
                ll z=*jt;
                ll cost=(x-y)*(x-y)+(y-z)*(y-z)+(z-x)*(z-x);
                best=min(best,cost);
            }
        }
        printf("%lld\n",best);
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        ll p,f; ll cs,cw,s,w;
        scanf("%lld %lld %lld %lld %lld %lld",&p,&f,&cs,&cw,&s,&w);
        if(s>w){ swap(s,w); swap(cs,cw); }   // s is the lighter weapon
        ll best=0;
        for(ll i=0;i<=cs && i*s<=p;i++){
            ll x=min(cw,(p-i*s)/w);          // you: max lighter-first, then heavier
            ll rs=cs-i, rw=cw-x;
            ll j=min(rs,f/s);                // follower: lighter first
            ll y=min(rw,(f-j*s)/w);
            best=max(best,i+x+j+y);
        }
        printf("%lld\n",best);
    }
}

