int main(){
    int t; scanf("%d",&t);
    while(t--){
        ll a,b,c; scanf("%lld %lld %lld",&a,&b,&c);
        if(c!=a+1){ puts("-1"); continue; }
        ll k=63-__builtin_clzll(c);
        ll S=c*k+2*(c-(1LL<<k));              // min sum of leaf depths of a binary tree with c leaves
        ll cl=(c==1)?0:(64-__builtin_clzll(c-1)); // ceil(log2 c)
        ll H=max(cl,(b+S+c-1)/c);
        printf("%lld\n",H);
    }
}

