#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll INF=LLONG_MAX/4;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; ll k; scanf("%d %lld",&n,&k);
        map<ll,vector<ll>> cls;
        for(int i=0;i<n;i++){ ll x; scanf("%lld",&x); cls[x%k].push_back(x); }
        int odd=0;
        for(auto&kv:cls) if(kv.second.size()%2) odd++;
        if(odd!=n%2){ puts("-1"); continue; }
        ll total=0;
        for(auto&kv:cls){
            auto v=kv.second; sort(v.begin(),v.end());
            int m=v.size();
            vector<ll> f0(m+1,INF), f1(m+1,INF);   // f0: no skip, f1: the single skip used
            f0[0]=0;
            for(int i=0;i<m;i++){
                if(f0[i]<INF && i+1<m) f0[i+2]=min(f0[i+2],f0[i]+(v[i+1]-v[i]));
                if(f0[i]<INF) f1[i+1]=min(f1[i+1],f0[i]);
                if(f1[i]<INF && i+1<m) f1[i+2]=min(f1[i+2],f1[i]+(v[i+1]-v[i]));
            }
            ll cost=(m%2==0)?f0[m]:f1[m];
            total+=cost/k;
        }
        printf("%lld\n",total);
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; ll m; scanf("%d %lld",&n,&m);
        vector<ll> a(n+2);
        for(int i=1;i<=n;i++) scanf("%lld",&a[i]);
        vector<ll> B(a.begin()+1,a.begin()+n+1);
        sort(B.begin(),B.end());
        // s = largest count of opponents we can prepare for within budget m
        int s=0; ll sum=0;
        while(s<n && sum+B[s]<=m){ sum+=B[s]; s++; }
        if(s==n){ puts("1"); continue; }
        // place = n - s + x, x=0 if opponent s+1 can be in the prepared set
        int x=1;
        if(s>=1){
            vector<ll> R; bool removed=false;
            for(ll v:B){ if(!removed && v==a[s+1]){ removed=true; continue; } R.push_back(v); }
            ll pre=0; for(int i=0;i<s-1;i++) pre+=R[i];
            if(a[s+1]+pre<=m) x=0;
        }
        printf("%d\n", n-s+x);
    }
}

