int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<long long> a(n);
        for(auto&x:a) scanf("%lld",&x);
        // any good array has length <= 4 (Erdos-Szekeres on distinct values; duplicates are bad)
        long long ans=0;
        for(int l=0;l<n;l++){
            int rmax=l;
            for(int r=l+1;r<n && r<=l+4;r++){
                bool bad=false;
                for(int i=l;i<r && !bad;i++)
                    for(int j=i+1;j<r && !bad;j++){
                        long long lo=min(a[i],a[r]), hi=max(a[i],a[r]);
                        if(a[j]>=lo && a[j]<=hi) bad=true;
                    }
                if(bad) break;
                rmax=r;
            }
            ans+=rmax-l+1;
        }
        printf("%lld\n",ans);
    }
}

