    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; ll k; scanf("%d %lld",&n,&k);
        vector<ll> a(n+1), g(n);
        ll sumA=0;
        for(int i=1;i<=n;i++){ scanf("%lld",&a[i]); sumA+=a[i]; }
        // jumping over trap i (1-based) has gain g_i = a_i - (n-i)
        for(int i=1;i<=n;i++) g[i-1]=a[i]-(n-i);
        sort(g.rbegin(),g.rend());
        ll best=0, pref=0;
        for(ll m=1;m<=min<ll>(k,n);m++){
            pref+=g[m-1];
            best=max(best, pref+m*(m-1)/2);
        }
        printf("%lld\n", sumA-best);
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<ll> h(n);
        ll S=0, M=0;
        for(auto&x:h){ scanf("%lld",&x); S+=x; M=max(M,x); }
        ll best=LLONG_MAX;
        for(ll H=M;H<=M+1;H++){
            ll sumd=(ll)n*H-S;
            ll cntOdd=0;
            for(ll x:h) if(((H-x)%2+2)%2==1) cntOdd++;
            auto feasible=[&](ll T){
                ll O=(T+1)/2, E=T/2;
                ll L=max(cntOdd, sumd-2*E);
                ll U=min(O,sumd);
                if(((U-sumd)%2+2)%2!=0) U--;
                return L<=U;
            };
            ll lo=0, hi=2*sumd+2;
            while(lo<hi){ ll mid=(lo+hi)/2; if(feasible(mid)) hi=mid; else lo=mid+1; }
            best=min(best,lo);
        }
        printf("%lld\n",best);
    }
}

#include <bits/stdc++.h>
using namespace std;
int par[200005];
int fnd(int x){ while(par[x]!=x){ par[x]=par[par[x]]; x=par[x]; } return x; }
int main(){
    int n,m; scanf("%d %d",&n,&m);
    for(int i=1;i<=n;i++) par[i]=i;
    vector<int> diff(n+2,0);
    for(int i=0;i<m;i++){
        int u,v; scanf("%d %d",&u,&v);
        if(u>v) swap(u,v);
        diff[u]++; diff[v]--;   // boundaries u..v-1 are crossed by this edge
        int a=fnd(u), b=fnd(v);
        if(a!=b) par[a]=b;
    }
    int C=0;
    for(int i=1;i<=n;i++) if(fnd(i)==i) C++;
    // F = number of final intervals = uncovered boundaries (i in 1..n, boundary after i)
    int F=0, cov=0;
    for(int i=1;i<=n;i++){
        cov+=diff[i];
        if(cov==0) F++;
    }
    printf("%d\n", C-F);
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<vector<int>> adj(n+1);
        for(int i=0;i<n-1;i++){ int u,v; scanf("%d %d",&u,&v); adj[u].push_back(v); adj[v].push_back(u); }
        vector<int> dep(n+1,-1), par(n+1,0), order; order.reserve(n);
        dep[1]=0; order.push_back(1);
        for(size_t h=0;h<order.size();h++){
            int v=order[h];
            for(int w:adj[v]) if(dep[w]<0){ dep[w]=dep[v]+1; par[w]=v; order.push_back(w); }
        }
        vector<int> md(n+1);
        for(int v=1;v<=n;v++) md[v]=dep[v];
        for(int h=n-1;h>=1;h--){ int v=order[h]; md[par[v]]=max(md[par[v]],md[v]); }
        int maxd=0; for(int v=1;v<=n;v++) maxd=max(maxd,dep[v]);
        // cover[D] = #vertices v with dep[v] <= D <= md[v]; keeping them gives leaves all at depth D
        vector<int> diff(maxd+2,0);
        for(int v=1;v<=n;v++){ diff[dep[v]]++; diff[md[v]+1]--; }
        int cov=0, best=0;
        for(int D=0;D<=maxd;D++){ cov+=diff[D]; if(D>=1) best=max(best,cov); }
        printf("%d\n", n-best);
    }
}

