int main(){
    static char buf[100005];
    scanf("%s",buf);
    string s(buf); int n=s.size();
    vector<char> suf(n+1,'{');   // '{' sorts after 'z'
    for(int i=n-1;i>=0;i--) suf[i]=min(s[i],suf[i+1]);
    string u; vector<char> st;
    for(int i=0;i<n;i++){
        st.push_back(s[i]);
        while(!st.empty() && st.back()<=suf[i+1]){ u.push_back(st.back()); st.pop_back(); }
    }
