    printf("%s\n",u.c_str());
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; ll m; scanf("%d %lld",&n,&m);
        vector<ll> a(n), c(n);
        for(auto&x:a) scanf("%lld",&x);
        for(auto&x:c) scanf("%lld",&x);
        vector<int> ord(n); iota(ord.begin(),ord.end(),0);
        sort(ord.begin(),ord.end(),[&](int i,int j){return a[i]<a[j];});
        vector<ll> A(n), C(n);
        for(int i=0;i<n;i++){ A[i]=a[ord[i]]; C[i]=c[ord[i]]; }
        ll best=0;
        for(int i=0;i<n;i++){
            ll v=A[i], cv=C[i];
            ll cv1=(i+1<n && A[i+1]==v+1)?C[i+1]:0;
            // max t flowers from values {v, v+1} within budget m
            auto feas=[&](ll t){
                ll yMin=max(0LL,t-cv);
                return t*v+yMin<=m;
            };
            ll lo=0, hi=cv+cv1;
            while(lo<hi){ ll mid=(lo+hi+1)/2; if(feas(mid)) lo=mid; else hi=mid-1; }
            ll t=lo;
            if(t==0) continue;
            ll y=min({cv1, t, m-t*v});
            best=max(best, t*v+y);
        }
        printf("%lld\n",best);
    }
}
